pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let time_ratio = (step_index as f64 / total_items as f64).powi(3);
    let residual_weight = if bin_residual > 0 { 1.0 } else { 0.8 };
    let next_item_fit = if next_item_size <= bin_capacity - post_residual { 0.25 } else { 0.0 };
    let fitting_bins_bonus = (fitting_bins_count as f64).powi(2) * 0.01;
    let open_bins_penalty = (open_bins_count as f64).ln() * -0.7;
    let mean_residual_effect = if mean_residual > bin_capacity / 3 { -0.2 } else { 0.0 };
    let post_residual_effect = if post_residual > 0 { 0.1 } else { 0.0 };

    let score = time_ratio * residual_weight + next_item_fit + fitting_bins_bonus + open_bins_penalty + mean_residual_effect + post_residual_effect;

    score
}

